{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TEMP TABLE Inventory_Data_Base AS select location, Company_Token, Brand, DATETIME_SUB(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Report_Generated_Date),INTERVAL 2 HOUR) DATA_FETCH_DATE, replace(replace(SKU,\'`\',\'\'),\'\\'\',\'\') SKU, split(replace(UPPER(trim(parts[SAFE_OFFSET(ARRAY_LENGTH(parts) - 1)])),\'_\',\'\'),\'/Z\')[SAFE_OFFSET(0)] as sku_size, replace(replace(parts[safe_offset(0)],\'`\',\'\'),\'\\'\',\'\') sku_style, upper(Product_Name) as PRODUCTNAME, repair, damaged, received, (cast(Amazon_Reserved as INT64) + cast(Reserved__Picked_ as INT64) + cast(Reserved__Not_Picked_ as INT64)) reserved, QC_Failed, QC_Passed, QC_Pending, Total_Lost, ifnull(cast(Available_Quantity as INT64),0) Available_Quantity, Undispatched_Unassigned_Quantity from (select *,ARRAY( SELECT part FROM UNNEST(SPLIT(replace(sku,\'_\',\'-\'), \'-\')) AS part WHERE part != \'\' ) as parts from maplemonk.EasyEcom_goodtribe_easyecom_inventory_snapshot) qualify row_number() over (partition by location, Company_Token, SKU, cast(DATA_FETCH_DATE as date) order by DATA_FETCH_DATE) = 1; CREATE TEMP TABLE All_SKU_Dates AS SELECT DISTINCT c.date_day, d.sku, d.location, d.company_token, d.sku_style, d.sku_size, d.brand FROM Inventory_Data_Base AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c ; CREATE TEMP TABLE Inventory_Data AS SELECT cast(d.DATE_DAY as date) DATA_FETCH_DATE, d.SKU, d.BRAND, SUM(i.Available_Quantity) AS AVAILABLEINVENTORY FROM All_SKU_Dates d LEFT JOIN Inventory_Data_Base i ON lower(d.sku) = lower(i.sku) and d.date_day = date(i.Data_Fetch_Date) and d.location = i.location and d.company_token = i.company_token GROUP BY 1,2,3; CREATE TEMP TABLE Sales_Data_Daily AS SELECT cast(order_date as date) Order_date, REPLACE(coalesce(commonsku, sku), \'\\'\', \'\') AS SKU, SUM(IFNULL(quantity, 0)) AS QUANTITY, SUM(IFNULL(returned_quantity, 0)) AS RETURNED_QUANTITY, SUM(IFNULL(SELLING_PRICE,0)) SELLING_PRICE FROM maplemonk.goodtribe_wh_sales_consolidated where (not(lower(order_status) like any (\'%cancel%\',\'%return%\') or lower(FINAL_SHIPPING_STATUS) like any (\'%cancel%\',\'%return%\'))) and cast(order_date as date) < (select max(DATA_FETCH_DATE) from Inventory_Data) GROUP BY 1,2; CREATE TEMP TABLE PRE_Sales_DRR AS select cast(coalesce(order_date,DATA_FETCH_DATE) as date) as Date ,coalesce(ID.SKU,SD.SKU) as SKU ,ifnull(sd.QUANTITY,0) as Quantity ,ifnull(id.AVAILABLEINVENTORY,0) as Available_Inventory ,case when ifnull(id.AVAILABLEINVENTORY,0) > ifnull(sd.QUANTITY,0) then 1 else 0 end as drr_flag from Sales_Data_Daily sd full outer join Inventory_Data ID on cast(ID.DATA_FETCH_DATE as date) = cast(sd.order_date as date) and lower(id.SKU) = lower(sd.SKU) ; CREATE TEMP TABLE Final_DRR AS select pd.date ,pd.sku ,sum(case when pdr.drr_flag = 1 then pdr.Quantity else 0 end) as drr_quantity ,sum(pdr.drr_flag) as drr_days from PRE_Sales_DRR pd left join PRE_Sales_DRR pdr on pd.sku = pdr.sku and DATE_DIFF(pd.date, pdr.date, DAY) <= 30 and DATE_DIFF(pd.date, pdr.date, DAY) > 0 group by 1,2 ; CREATE TEMP TABLE Actual_Sales_Daily AS SELECT Date as Order_date, SKU, Quantity, CASE WHEN drr_flag = 1 THEN Quantity ELSE 0 END AS Valid_Quantity, CASE WHEN drr_flag = 1 THEN (SELECT SUM(SELLING_PRICE) FROM Sales_Data_Daily s WHERE s.SKU = ps.SKU AND s.Order_date = ps.Date) ELSE 0 END AS Valid_Selling_Price FROM PRE_Sales_DRR ps; CREATE TEMP TABLE Sales_Weekly_Stats AS WITH WeeklyAgg AS ( SELECT DATE_TRUNC(Order_date, WEEK) AS week_Start, SKU, SUM(Valid_Quantity) AS Weekly_Qty, SUM(Valid_Selling_Price) AS Weekly_Price FROM Actual_Sales_Daily WHERE DATE_DIFF(CURRENT_DATE(), Order_date, DAY) <= 56 GROUP BY 1, 2 ) SELECT SKU, MAX(Weekly_Qty) AS Max_Weekly_Sales, MIN(Weekly_Qty) AS Min_Weekly_Sales FROM WeeklyAgg GROUP BY 1; CREATE TEMP TABLE INVENTORY_FINAL AS SELECT ID.DATA_FETCH_DATE, EXTRACT(DAY FROM DATE_SUB(ID.DATA_FETCH_DATE, INTERVAL 1 DAY)) AS mtd_Days, ID.SKU, MAX(IFNULL(CAST(ID.AVAILABLEINVENTORY AS FLOAT64), 0)) AS Available_Inventory, MAX(WS.Max_Weekly_Sales) AS Max_Weekly_Sales, MAX(WS.Min_Weekly_Sales) AS Min_Weekly_Sales, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 55 THEN CS.Valid_Quantity ELSE 0 END) AS Sold_Quantity_56_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 29 THEN CS.Valid_Quantity ELSE 0 END) AS Sold_Quantity_30_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 13 THEN CS.Valid_Quantity ELSE 0 END) AS Sold_Quantity_14_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 6 THEN CS.Valid_Quantity ELSE 0 END) AS Sold_Quantity_7_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) = 1 THEN CS.Valid_Quantity ELSE 0 END) AS Sold_Quantity_last_day, SUM(CASE WHEN DATE_TRUNC(CS.Order_date, MONTH) = DATE_TRUNC(ID.DATA_FETCH_DATE, MONTH) AND CS.Order_date < ID.DATA_FETCH_DATE THEN CS.Valid_Quantity ELSE 0 END) AS sold_quantity_mtd, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 55 AND CS.drr_flag = 1 THEN 1 ELSE 0 END) AS In_Stock_Days_56, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 29 AND CS.drr_flag = 1 THEN 1 ELSE 0 END) AS In_Stock_Days_30, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 13 AND CS.drr_flag = 1 THEN 1 ELSE 0 END) AS In_Stock_Days_14, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 6 AND CS.drr_flag = 1 THEN 1 ELSE 0 END) AS In_Stock_Days_7, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) = 1 AND CS.drr_flag = 1 THEN 1 ELSE 0 END) AS In_Stock_Days_last_day, SUM(CASE WHEN DATE_TRUNC(CS.Order_date, MONTH) = DATE_TRUNC(ID.DATA_FETCH_DATE, MONTH) AND CS.Order_date < ID.DATA_FETCH_DATE AND CS.drr_flag = 1 THEN 1 ELSE 0 END) AS In_Stock_Days_mtd, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 55 THEN CS.Valid_Selling_Price ELSE 0 END) AS Selling_Price_56_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 29 THEN CS.Valid_Selling_Price ELSE 0 END) AS Selling_Price_30_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 13 THEN CS.Valid_Selling_Price ELSE 0 END) AS Selling_Price_14_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) BETWEEN 0 AND 6 THEN CS.Valid_Selling_Price ELSE 0 END) AS Selling_Price_7_Days, SUM(CASE WHEN DATE_DIFF(ID.DATA_FETCH_DATE, CS.Order_date, DAY) = 1 THEN CS.Valid_Selling_Price ELSE 0 END) AS Selling_Price_last_day, SUM(CASE WHEN DATE_TRUNC(CS.Order_date, MONTH) = DATE_TRUNC(ID.DATA_FETCH_DATE, MONTH) AND CS.Order_date < ID.DATA_FETCH_DATE THEN CS.Valid_Selling_Price ELSE 0 END) AS Selling_Price_mtd FROM Inventory_Data ID LEFT JOIN ( SELECT ps.Date as Order_date, ps.SKU, ps.drr_flag, CASE WHEN ps.drr_flag = 1 THEN ps.Quantity ELSE 0 END AS Valid_Quantity, CASE WHEN ps.drr_flag = 1 THEN (SELECT SUM(SELLING_PRICE) FROM Sales_Data_Daily s WHERE s.SKU = ps.SKU AND s.Order_date = ps.Date) ELSE 0 END AS Valid_Selling_Price FROM PRE_Sales_DRR ps ) CS ON LOWER(ID.SKU) = LOWER(CS.SKU) AND CS.Order_date < ID.DATA_FETCH_DATE AND CS.Order_date >= DATE_SUB(ID.DATA_FETCH_DATE, INTERVAL 56 DAY) LEFT JOIN Sales_Weekly_Stats WS ON LOWER(ID.SKU) = LOWER(WS.SKU) GROUP BY 1, 2, 3; CREATE OR REPLACE TABLE MAPLEMONK.GOODTRIBE_WH_INVENTORY_FACT_ITEMS AS SELECT IFT.DATA_FETCH_DATE, IFT.mtd_Days, IFT.SKU, coalesce(SM.Product_Name) AS Product_Final_Name, SM.PRODUCT_CATEGORY, SM.Colour, SM.SIZE, SM.image, SM.PRODUCT_image_URL, S.Image AS style_image, CASE WHEN DATE_DIFF(CURRENT_DATE(), sfi.product_launch_date, DAY) <= 30 THEN \'New Launch\' ELSE \'Old Launch\' END AS Product_Launch_Status, IFT.Available_Inventory, IFT.Max_Weekly_Sales, IFT.Min_Weekly_Sales, IFT.Sold_Quantity_56_Days, IFT.Sold_Quantity_30_Days, IFT.Sold_Quantity_14_Days, IFT.Sold_Quantity_7_Days, IFT.Sold_Quantity_last_day, IFT.sold_quantity_mtd, IFT.Selling_Price_56_Days, IFT.Selling_Price_30_Days, IFT.Selling_Price_14_Days, IFT.Selling_Price_7_Days, IFT.Selling_Price_last_day, IFT.Selling_Price_mtd, IFT.In_Stock_Days_56, IFT.In_Stock_Days_30, IFT.In_Stock_Days_14, IFT.In_Stock_Days_7, IFT.In_Stock_Days_last_day, IFT.In_Stock_Days_mtd, PU.Cutting_total, FD.drr_quantity, FD.drr_days FROM INVENTORY_FINAL IFT LEFT JOIN ( SELECT * FROM ( SELECT TRIM(SPLIT(product_name, \'-\')[OFFSET(0)]) AS product_name, category_name AS product_category, product_image_url, sku, UPPER(colour) AS COLOUR, UPPER(SIZE) AS SIZE, CAST(mrp AS FLOAT64) AS mrp, CAST(cost AS FLOAT64) AS cost, CONCAT(\'<img src=\"\', product_image_url, \'\" width=\"70\">\') AS Image, ROW_NUMBER() OVER (PARTITION BY LOWER(sku) ORDER BY 1) AS rw FROM MAPLEMONK.EasyEcom_goodtribe_easyecom_product_master ) WHERE rw = 1 ) SM ON LOWER(IFT.SKU) = LOWER(SM.SKU) LEFT JOIN ( SELECT style, MAX(image) AS image FROM ( SELECT TRIM(SPLIT(UPPER(sku), \'-\')[OFFSET(0)]) AS style, CONCAT(\'<img src=\"\', product_image_url, \'\" width=\"70\">\') AS Image, ROW_NUMBER() OVER (PARTITION BY TRIM(SPLIT(UPPER(sku), \'-\')[OFFSET(0)]) ORDER BY 1) AS rw FROM MAPLEMONK.EasyEcom_goodtribe_easyecom_product_master ) WHERE rw = 1 GROUP BY 1 ) S ON TRIM(SPLIT(UPPER(IFT.SKU), \'-\')[OFFSET(0)]) = UPPER(S.style) LEFT JOIN Final_DRR FD ON CAST(IFT.DATA_FETCH_DATE AS DATE) = CAST(FD.date AS DATE) AND LOWER(IFT.SKU) = LOWER(FD.SKU) LEFT JOIN ( SELECT UPPER(sku) AS sku, DATE(product_launch_date) AS product_launch_date FROM MAPLEMONK.goodtribe_wh_shopify_fact_items QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(sku) ORDER BY 1) = 1 ) sfi ON TRIM(UPPER(IFT.SKU)) = UPPER(sfi.SKU) LEFT JOIN ( SELECT * FROM maplemonk.GS_SKU_level_Processing_units QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(id) ORDER BY id) = 1 ) PU ON LOWER(IFT.SKU) = LOWER(PU.id);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            